insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 7, 'O quanto ela glorificou a si mesma, e viveu sensualmente, tanto quanto dai a ela [de] tormento e pranto; porque ela em seu coração diz: ‘Eu estou assentada [como] rainha e não sou viúva, e nenhum pranto eu verei.’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 8, 'Portanto em um dia virão as pragas sobre ela: morte, pranto e fome; e ela será queimada com fogo; porque forte [é] o Senhor Deus, que a julga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 9, 'E os reis da terra, que se prostituíram com ela, e viveram sensualmente, prantearão por ela, quando virem a fumaça de sua queima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 10, 'Estando de longe, por medo do tormento dela, dizendo: ‘Ai, ai daquela grande cidade de Babilônia, aquela forte cidade! Porque em uma hora veio o teu julgamento.’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 11, 'E os comerciantes da terra choram e lamentam sobre ela, porque ninguém mais compra as mercadorias deles:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 12, 'mercadoria de ouro, e de prata, e de pedras preciosas, e de pérolas, e de linho fino, e de púrpura, e de seda, e de escarlate; e de toda madeira aromática, e de todo objeto de marfim, e de todo objeto de madeira valiosíssima, e liga de cobre, e de ferro, e de mármore;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 13, 'e canela, e perfumes, e óleo aromático, e incenso, e vinho, e azeite, e farinha fina, e trigo, e gado, e ovelhas; e de cavalos, e de carruagens, e de corpos e almas humanas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 14, 'E o fruto do mau desejo de tua alma foi embora de ti; e todas as coisas deliciosas e excelentes foram embora de ti; e tu não mais as acharás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 15, 'Os comerciantes dessas coisas, que por ela se enriqueceram, estarão de longe por medo do tormento dela, chorando e lamentando,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 16, 'E dizendo: ‘Ai, ai daquela grande cidade, que estava vestida de linho fino, e púrpura, e escarlate; e adornada com ouro, pedras preciosas, e pérolas! Porque em uma hora tantas riquezas foram assoladas.’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 17, 'E todo capitão de embarcação, e todos da multidão que [estavam] em barcos, e marinheiros, e todos os que trabalham no mar, se puseram de longe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 18, 'e vendo a fumaça da queima dela, clamaram, dizendo: ‘[Havia] algo comparável a esta grande cidade?’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 19, 'E eles lançaram pó em suas cabeças, e clamaram, chorando e lamentando, dizendo: ‘Ai, ai daquela grande cidade, em que todos os que tinham barcos no mar se enriqueceram da opulência dela! Porque em uma hora ela foi assolada.’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 20, '“Alegra-te sobre ela, ó céu; e [também] vós santos apóstolos e profetas; porque Deus [já] julgou contra ela a vossa causa.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 21, 'E um forte anjo levantou uma pedra, como uma grande pedra de moinho, e [a] lançou no mar, dizendo: “Com tal violência Babilônia será lançada, aquela grande cidade, e não mais será achada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 22, 'E voz de harpistas, e de músicos, e de flautistas, e de tocadores de trombeta, não mais se ouvirá em ti; e nenhum artesão de toda arte não mais se achará em ti; e ruído de moinho não mais se ouvirá em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 23, 'E luz de lâmpada não mais iluminará em ti; e voz de noivo e de noiva não mais se ouvirá em ti; porque teus comerciantes eram os grandes da terra, porque por tuas feitiçarias todas as nações foram enganadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 24, 'E nela se achou o sangue dos profetas e dos santos, e de todos os que foram mortos sobre a terra.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 1, 'E depois destas coisas, eu ouvi uma voz de uma grande multidão no céus, que dizia: “Aleluia! Salvação, glória, honra, e poder ao Senhor, nosso Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 2, 'Porque verdadeiros e justos são seus juízos; pois ele julgou a grande prostituta, que com sua prostituição corrompia a terra, e vingou da mão dela o sangue dos servos dele.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 3, 'E disseram pela segunda vez: “Aleluia! E a fumaça dela sobe para todo o sempre.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 4, 'E os vinte e quatro anciãos, e os quatro animais, se prostraram, e adoraram a Deus (que [estava] sentado no trono) [e] diziam: “Amém! Aleluia!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 5, 'E saiu uma voz do trono, dizendo: “Louvai ao nosso Deus, todos vós os servos dele, e vós que o temeis, tanto pequenos como grandes.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 6, 'E eu ouvi como a voz de uma grande multidão, e como a voz de muitas águas, e como a voz de fortes trovões, dizendo: “Aleluia! Porque o Senhor Deus Todo-Poderoso reina!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 7, 'Alegremos, e fiquemos muito contentes, e demos glória a ele, pois [já] chegou a festa de casamento do Cordeiro, e a sua esposa já se preparou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 8, 'E foi concedido a ela que se vestisse de linho fino puro e brilhante; pois o linho fino são as justiças dos santos.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 9, 'E ele me disse: Escreve: “Benditos [são] aqueles que foram chamados para a ceia da festa de casamento do Cordeiro.” E ele me disse: “Estas são as verdadeiras palavras de Deus.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 10, 'E eu me lancei aos pés dele para o adorar; mas ele me disse: “Olha, não [faças isso] ! Eu [também] sou companheiro de serviço teu, e de teus irmãos, que têm o testemunho de Jesus; adora a Deus; porque o testemunho de Jesus é o espírito da profecia.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 11, 'E eu vi o céu aberto; e eis um cavalo branco; e o que estava sentado sobre ele era chamado Fiel e Verdadeiro, e em justiça ele julga e guerreia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 12, 'E os olhos dele [eram] como uma chama de fogo; e sobre a cabeça dele [havia] muitas diademas, e ele tinha um nome escrito, que ninguém sabia, a não ser ele mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 13, 'E ele estava vestido de uma roupa tingida em sangue, e o nome dele é chamado “Palavra de Deus”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 14, 'E os exércitos no céu o seguiam em cavalos brancos, vestidos de linho fino branco e puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 15, 'E da boca dele saía uma espada afiada, para com ela ferir às nações; e ele as dominará com vara de ferro; e ele pisa na prensa do vinho da ira e da indignação do Deus Todo-Poderoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 16, 'E ele tem sobre [sua] roupa e sobre sua coxa escrito [este] nome: “Rei dos Reis, e Senhor dos Senhores”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 17, 'E eu vi um anjo que estava no sol; e ele clamou em alta voz, dizendo a todas as aves que voavam no meio do céu: “Vinde, e ajuntai-vos para a ceia do grande Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 18, 'para que comais a carne dos reis, e a carne dos chefes militares, e a carne dos fortes, e a carne dos cavalos e dos que se assentam sobre eles; e a carne de todos os livres e servos; e dos pequenos e dos grandes.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 19, 'E eu vi a besta, e os reis da terra, e os exércitos deles juntos, para fazerem guerra contra aquele que estava sentado sobre o cavalo, e contra o exército dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 20, 'E a besta foi presa, e com ela o falso profeta, que diante dela fazia os sinais sobrenaturais, com os quais tinha enganado aos que receberam a marca da besta, e adoraram à imagem dela. Estes dois foram lançados vivos no lago do fogo ardente em enxofre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 19, 21, 'E os restantes foram mortos com a espada que saía da boca daquele que estava sentado sobre o cavalo; e as aves se saciaram com as carnes deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 1, 'E eu vi um anjo descendo do céu, tendo a chave do abismo; e uma grande corrente em sua mão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 2, 'E ele deteve ao dragão, e à antiga serpente, que é o diabo e Satanás, e o amarrou por mil anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 3, 'E o lançou no abismo, e ali o prendeu, e o selou sobre ele; para que não mais enganasse às nações, até que se completem os mil anos; e depois disto é necessário que ele seja solto por um pouco de tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 4, 'E eu vi tronos, e se assentaram sobre eles, e foi concedido a eles o julgamento; e [eu vi] as almas daqueles que tinham sido degolados por causa do testemunho de Jesus, e por causa da palavra de Deus; e que não tinham adorado à besta, nem à imagem dela; e que não receberam a marca [dela] sobre suas testas, e sobre suas mãos; e eles viveram e reinaram com Cristo por mil anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 5, 'Mas os outros mortos não reviveram, enquanto não se completassem os mil anos. Esta [é] a primeira ressurreição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 6, 'Bendito e santo [é] aquele que tem parte na primeira ressurreição; sobre estes a segunda morte não tem poder; mas sim, eles serão sacerdotes de Deus e de Cristo, e com ele reinarão por mil anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 7, 'E quando se completarem os mil anos, Satanás será solto de sua prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 8, 'E ele sairá para enganar às nações, que estão nos quatro cantos da terra; a Gogue, e a Magogue, para os ajuntar em batalha; dos quais o numero [é] como a areia do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 9, 'E eles subiram sobre a largura da terra, e cercaram o acampamento dos santos, e a cidade amada; e desceu fogo do céu [vindo] de Deus; e os consumiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 10, 'E o diabo, que os enganava, foi lançado no lago de fogo e enxofre, onde [estão] a besta e o falso profeta; e serão atormentados dia e noite para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 11, 'E eu vi um grande trono branco, e o que estava assentado sobre ele; do rosto dele a terra e o céu fugiram, e não foi achado lugar para eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 12, 'E eu vi os mortos, grandes e pequenos, estarem de pé diante de Deus; e os livros foram abertos; e outro livro foi aberto (que é o [livro] da vida); e os mortos foram julgados pelas coisas que estavam escritas nos livros, segundo as obras deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 13, 'E o mar entregou os mortos que nele havia; e a morte e o Xeol entregaram os mortos que neles havia; e foram julgados cada um segundo as obras deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 14, 'E a morte e o Xeol foram lançados no lago de fogo; esta é a segunda morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 20, 15, 'E todo aquele que não fosse achado escrito no livro da vida foi lançado no lago de fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 1, 'E eu vi um novo céu e uma nova terra; porque o primeiro céu e a primeira terra [já] passaram; e e [já] não havia mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 2, 'E eu, João, vi a cidade santa, a nova Jerusalém, descendo do céu [vinda] de Deus, preparada como noiva, adornada para seu marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 3, 'E eu ouvi uma grande voz do céu, dizendo: “Eis que o tabernáculo de Deus está com os seres humanos; e com eles habitará, e eles serão seu povo, e o próprio Deus estará com eles, [e será] seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 4, 'E Deus limpará toda lágrima dos olhos deles; e não haverá mais morte, nem pranto, nem clamor, nem mais haverá dor; porque as primeiras coisas [já] passaram.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 5, 'E o que estava sentado sobre o trono disse: “Eis que eu faço novas todas as coisas.” E ele me disse: “Escreve, porque estas palavras são verdadeiras e fiéis.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 6, 'E ele me disse: “Está feito. Eu sou o Alfa e o Ômega, o princípio e o fim. Quem tiver sede, de graça eu lhe darei da fonte da água da vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 7, 'Quem vencer herdará todas as coisas; e eu serei Deus dele, e ele será meu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 8, 'Mas [quanto] aos covardes, e aos incrédulos, e aos abomináveis, e aos homicidas, e aos pecadores sexuais, e aos feiticeiros, e aos idólatras, e a todos os mentirosos, a parte deles será no lago que queima com fogo e enxofre, que é a segunda morte.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 9, 'E veio a mim um dos sete anjos que tinham as sete taças cheias das sete últimas pragas; e ele falou comigo, dizendo: “Vem, [e] eu te mostrarei a noiva, a mulher do Cordeiro.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 10, 'E ele me levou em espírito a um grande e alto monte; e ele me mostrou a grande cidade, a santa Jerusalém, descendo do céu [vinda] de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 11, '[E] tendo a glória de Deus; e sua luz era semelhante a uma pedra preciosíssima, como a pedra de jaspe, como cristal brilhante;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 12, '[E] tinha um grande e alto muro tendo doze portas; e nas portas doze anjos, e nomes escritos nelas, que são os [nomes] das doze tribos dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 13, 'No oriente [tinha] três portas; no norte três portas, no sul três portas, [e] no ocidente três portas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 14, 'E o muro da cidade tinha doze fundamentos, e neles os nomes dos doze apóstolos do Cordeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 15, 'E aquele que estava falando comigo tinha uma cana de ouro, para medir a cidade, e suas portas, e seu muro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 16, 'E a cidade estava posta [na forma] de um quadrado; e o seu comprimento era tanto quanto [sua] largura. E ele mediu a cidade com a cana até doze mil estádios; e seu comprimento, largura e altura eram iguais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 17, 'E ele mediu seu muro de cento e quarenta e quatro côvados, [conforme] a medida humana, que é [também] a do anjo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 18, 'E a constituição de seu muro era [de] jaspe; e a cidade [era] de ouro puro, semelhante a vidro puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 19, 'E os fundamentos do muro da cidade estavam adornados com toda pedra preciosa; o primeiro fundamento era jaspe; o segundo, safira; o terceiro, calcedônia; o quarto, esmeralda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 20, 'O quinto, sardônica; o sexto, sárdio; o sétimo, crisólito; o oitavo, berilo; o nono, topázio; o décimo, crisópraso; o décimo primeiro, jacinto; o décimo segundo, ametista.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 21, 'E as doze portas eram doze pérolas; cada uma das portas era de uma pérola; e a praça da cidade [era] de ouro puro, como vidro transparente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 22, 'E nela eu não vi templo, porque o templo dela é o Senhor Deus Todo-Poderoso, e o Cordeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 23, 'E a cidade não necessita de sol nem de lua para que brilhem nela; porque a glória de Deus a ilumina, e sua lâmpada [é] o Cordeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 24, 'E as nações dos salvos andarão na luz dela; e os reis da terra trarão a ela a glória e honra deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 25, 'E suas portas não se fecharão de dia; porque ali não haverá noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 26, 'E a ela serão trazidas a glória e a honra das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 21, 27, 'E de maneira nenhuma entrará nela algo que contamine, faça abominação e mentira; a não ser somente aqueles que estão escritos no livro da vida do Cordeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 1, 'E ele me mostrou o rio puro da água da vida, claro como cristal, que vinha do trono de Deus e do Cordeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 2, 'No meio de sua praça, e de um lado e do outro do rio, [estava] a árvore da vida, que produz doze frutos, dando seu fruto a cada mês; e as folhas das árvores são para a saúde das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 3, 'E não haverá mais maldição alguma; e nela estará o trono de Deus e do Cordeiro, e seus servos o servirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 4, 'E eles verão o rosto dele, e o nome dele [estará] em suas testas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 5, 'E ali não haverá mais noite, e não terão necessidade de lâmpada, nem de luz do sol; porque o Senhor Deus os ilumina; e reinarão para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 6, 'E ele me disse: “Estas palavras são fiéis e verdadeiras; e o Senhor, o Deus dos santos profetas, enviou o seu anjo para mostrar a seus servos as coisas que devem acontecer em breve.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 7, '“Eis que logo venho; bendito [é] aquele que guarda as palavras da profecia deste livro.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 8, 'E eu, João, sou aquele que vi e ouvi estas coisas. E quando eu [as] ouvi e vi, prostrei-me para adorar diante dos pés do anjo, que me mostrava estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 9, 'E ele me disse: “Olha, não [faças isto] ! Porque eu sou um companheiro de serviço teu, e de teus irmãos, os profetas, e dos que guardam as palavras deste livro. Adora a Deus.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 10, 'E ele me disse: “Não seles as palavras da profecia deste livro, porque o tempo está próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 11, 'Quem é injusto, faça injustiça ainda; e quem é sujo, suje-se ainda; e quem é justo, seja ainda justificado; e quem é santo, seja ainda santificado.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 12, '“Eis que logo venho, e minha recompensa está comigo, para retribuir a cada um assim como for sua obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 13, 'Eu sou o Alfa e o Ômega, o principio e o fim, o primeiro e o último.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 14, 'Benditos são os que guardam os mandamentos dele, para que tenham direito à árvore da vida, e possam entrar na cidade pelas portas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 15, 'Mas de fora [estarão] os cães, os feiticeiros, os pecadores sexuais, os homicidas, os idólatras, e todo aquele que ama e pratica a mentira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 16, '“Eu, Jesus, enviei o meu anjo, para vos dar testemunho destas coisas nas igrejas. Eu sou a raiz e descendência de Davi; [sou] a brilhante estrela da manhã.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 17, 'E o Espírito e a noiva dizem: “Vem!” E quem [o] ouve, diga: “Vem!” E quem tem sede, venha; e quem quiser, tome de graça da água da vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 18, 'Porque eu também dou testemunho a todo aquele que ouvir as palavras da profecia deste livro, [que] se alguém acrescentar a estas, Deus lhe acrescentará as pragas que estão escritas neste livro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 19, 'E se alguém tirar das palavras do livro desta profecia, Deus tirará sua parte do livro da vida, e da cidade santa, e das coisas que estão escritas neste livro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 20, 'Aquele que dá testemunho destas coisas diz: “Certamente logo venho.” Amém! Sim, vem, Senhor Jesus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 22, 21, 'A graça do nosso Senhor Jesus Cristo [seja] com todos vós. Amém!')
